p179:
  fecha-en-nombre: yyMMdd          # WKS-ETIQ-*-FEC es 9(6): el MOVE desde 9(8) descarta el siglo
  entradas:                        # orden significativo: primero MTY, luego VDM
    - { nodo: 4,  csi: 4,  ruta: "(S500)S500/FILE/S111/04/DEPINICIAL/{fecha}." }
    - { nodo: 10, csi: 10, ruta: "(S500)S500/FILE/S111/10/DEPINICIAL/{fecha}." }
  salida: "(S500)S500/FILE/S111/DEPINICIAL/{fecha}."
  header:
    sistema-origen: "S500"
    sistema-destino: "S111"
    csi-origen: 10

